<?php
require_once 'common.php';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST')try{
 $client=filter_var($_POST['client_id']??'',FILTER_VALIDATE_INT);$id=filter_var($_POST['moving_id']??'',FILTER_VALIDATE_INT);$street=trim($_POST['destination_street_number']??'');$name=trim($_POST['destination_street_name']??'');$city=trim($_POST['destination_city']??'');$state=strtoupper(trim($_POST['destination_state']??''));$zip=trim($_POST['destination_zip']??'');$date=$_POST['moving_date']??'';$weight=filter_var($_POST['total_weight']??'',FILTER_VALIDATE_FLOAT);$miles=filter_var($_POST['miles']??'',FILTER_VALIDATE_FLOAT);$cost=filter_var($_POST['total_cost']??'',FILTER_VALIDATE_FLOAT);
 if(!$client||!$id||!$street||!$name||!$city||!preg_match('/^[A-Z]{2}$/',$state)||!preg_match('/^\d{5}(-\d{4})?$/',$zip)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!strtotime($date)||$weight===false||$weight<=0||$miles===false||$miles<0||$cost===false||$cost<0)throw new Exception('Invalid booking data.');
 $st=$pdo->prepare('INSERT INTO moving_events VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute([$id,$repId,$client,$street,$name,$city,$state,$zip,$date,$weight,$miles,$cost]);$msg='Moving event booked successfully.';
}catch(Throwable $e){$msg='Booking failed. Check all fields, unique event ID, and that the client belongs to your account.';}
pageStart('Book a Client Moving Event');if($msg)message($msg);echo '<form method="post">';clientSelect($pdo,$repId);foreach([['moving_id','Unique Moving Event ID','number'],['destination_street_number','Destination Street Number'],['destination_street_name','Destination Street Name'],['destination_city','Destination City'],['destination_state','Destination State (2 letters)'],['destination_zip','Destination ZIP'],['moving_date','Moving Date','date'],['total_weight','Total Weight','number'],['miles','Miles','number'],['total_cost','Total Cost','number']] as $f)field($f[0],$f[1],$f[2]??'text');submit('Book Moving Event');pageEnd();
